namespace UrlShortener.Api;

public static class VersionEndpoints
{
    public static IEndpointRouteBuilder MapVersionEndpoints(this IEndpointRouteBuilder app)
    {
        app.MapGet("/api/version", () => TypedResults.Ok(new VersionResponse(Version))).WithName("GetVersion");
        return app;
    }

    private static string Version =>
        typeof(VersionEndpoints).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? "unknown";
}

public sealed record VersionResponse(string Version);
